"""Dataset statistics -> reports/data_stats.md (regenerated by every build)."""

from __future__ import annotations

from collections import Counter, defaultdict
from pathlib import Path
from typing import Any

import numpy as np

from receipt_vlm.data.record import LABEL_KEYS

LOW_N = 50


def _md_table(header: list[str], rows: list[list[Any]]) -> str:
    out = ["| " + " | ".join(header) + " |", "|" + "---|" * len(header)]
    out += ["| " + " | ".join(str(c) for c in r) + " |" for r in rows]
    return "\n".join(out)


def _value(target: dict[str, Any], key: str) -> Any:
    if key.startswith("items."):
        attr = key.split(".", 1)[1]
        vals = [it.get(attr) for it in target.get("items") or []]
        return vals if any(v is not None for v in vals) else None
    return target.get(key)


def compute_stats(samples: dict[str, list[dict[str, Any]]]) -> dict[str, Any]:
    all_rows = [r for rows in samples.values() for r in rows]
    by_source: dict[str, list[dict[str, Any]]] = defaultdict(list)
    for r in all_rows:
        by_source[r["source"]].append(r)
    counts = {s: Counter(r["split"] for r in rows) for s, rows in by_source.items()}
    lang = Counter((r["language"], r["split"]) for r in all_rows)
    avail: dict[str, dict[str, tuple[float, float]]] = {}
    for s, rows in by_source.items():
        avail[s] = {}
        for key in LABEL_KEYS:
            lab = [r for r in rows if key in r["labelled"]]
            nonnull = [r for r in lab if _value(r["target"], key) not in (None, [])]
            avail[s][key] = (len(lab) / len(rows), len(nonnull) / len(lab) if lab else 0.0)
    items = {
        s: [len(r["target"]["items"]) for r in rows if "items.name" in r["labelled"]]
        for s, rows in by_source.items()
    }
    sizes = {
        s: np.median([[r["width"], r["height"]] for r in rows], axis=0)
        for s, rows in by_source.items()
    }
    return {"counts": counts, "lang": lang, "avail": avail, "items": items, "sizes": sizes}


def write_stats_report(
    samples: dict[str, list[dict[str, Any]]], info: dict[str, Any], path: Path
) -> None:
    st = compute_stats(samples)
    lines = [
        "# Dataset statistics",
        "",
        "_Generated by `make data` / `make synth` (`receipt_vlm.data.stats`). Do not edit by hand._",
        "",
        "## Samples per source and split",
        "",
    ]
    rows = []
    for s, c in sorted(st["counts"].items()):
        rows.append([s, c.get("train", 0), c.get("val", 0), c.get("test", 0), sum(c.values())])
    tot = [sum(r[i] for r in rows) for i in range(1, 5)]
    rows.append(["**total**", *tot])
    lines += [_md_table(["source", "train", "val", "test", "total"], rows), ""]

    lines += ["## Samples per stratification language and split", ""]
    langs = sorted({lang for lang, _ in st["lang"]})
    lrows = [
        [lang, *(st["lang"].get((lang, sp), 0) for sp in ("train", "val", "test"))]
        for lang in langs
    ]
    lines += [_md_table(["language", "train", "val", "test"], lrows), ""]
    low = [
        f"{lang} (test n={r[3]})"
        for lang, *_ in lrows
        for r in lrows
        if r[0] == lang and 0 < r[3] < LOW_N
    ]
    low += [
        f"{s} (test n={c.get('test', 0)})"
        for s, c in st["counts"].items()
        if 0 < c.get("test", 0) < LOW_N
    ]
    if low:
        lines += [
            f"Low-confidence test subgroups (< {LOW_N} samples): " + ", ".join(sorted(set(low))),
            "",
        ]

    lines += [
        "## Field label availability",
        "",
        "Each cell is `labelled% / non-null%`: the share of samples whose source annotates the "
        "field exhaustively (only these are scored), and among those the share where the field "
        "is actually printed. Unlabelled fields are never scored.",
        "",
    ]
    srcs = sorted(st["avail"])
    frows = [
        [
            key,
            *(
                f"{100 * st['avail'][s][key][0]:.0f} / {100 * st['avail'][s][key][1]:.0f}"
                for s in srcs
            ),
        ]
        for key in LABEL_KEYS
    ]
    lines += [_md_table(["field", *srcs], frows), ""]

    lines += ["## Items per receipt (samples with labelled items)", ""]
    irows = []
    for s, n in sorted(st["items"].items()):
        if n:
            irows.append([s, len(n), f"{np.mean(n):.1f}", int(np.median(n)), max(n)])
        else:
            irows.append([s, 0, "-", "-", "-"])
    lines += [_md_table(["source", "n", "mean", "median", "max"], irows), ""]

    lines += ["## Median stored image size (px)", ""]
    lines += [
        _md_table(
            ["source", "width", "height"],
            [[s, int(w), int(h)] for s, (w, h) in sorted(st["sizes"].items())],
        ),
        "",
    ]

    lines += ["## Build notes", ""]
    lines.append(f"- Dropped by dedup: {info.get('dropped') or 'none'}")
    lines.append(
        f"- Synthetic train samples removed by the share cap: {info.get('synthetic_train_capped', 0)}"
    )
    gaps = info.get("gaps") or {}
    if gaps:
        lines.append("- **Missing sources** (not in any split):")
        lines += [f"  - `{k}`: {v}" for k, v in sorted(gaps.items())]
    else:
        lines.append("- All configured sources were built.")
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text("\n".join(lines) + "\n", encoding="utf-8")
